9	/**
10	 * Rejects a create-owner request once 100 or more owners have already been registered today (by
11	 * {@code registrationDate}), responding 429 via {@link DailyLimitReachedException}. Runs before
12	 * {@link SaveOwner}, so the count excludes the owner being created.
13	 */
14	public class EnsureDailyLimit {
15	
16	    private static final int DAILY_LIMIT = 100;
17	
18	    public void service(OwnerRepository ownerRepository) throws DailyLimitReachedException {
19	        LocalDate today = LocalDate.now();
20	        int count = 0;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (today.equals(existing.getRegistrationDate())) {
23	                count++;
24	            }
25	        }
26	        if (count >= DAILY_LIMIT) {
27	            throw new DailyLimitReachedException(count);
28	        }
29	    }
30	}
